css:
.format-toolbar {
  display: inline-flex;
  align-items: center;
  gap: var(--va-space-gap-sm);
  padding: var(--va-space-inline-xs);
  background: var(--va-color-surface-default);
  border: 1px solid var(--va-color-border-subtle);
  border-radius: var(--va-radius-control);
}

.format-toolbar va-button {
  --va-button-padding-inline: var(--va-space-inline-sm);
}

.format-toolbar svg {
  display: block;
  inline-size: 1rem;
  block-size: 1rem;
}

js:
// Arrow-key navigation between buttons in the toolbar (WAI-ARIA toolbar pattern).
for (const toolbar of document.querySelectorAll('.format-toolbar')) {
  toolbar.addEventListener('keydown', (event) => {
    const buttons = [...toolbar.querySelectorAll('va-button:not([disabled])')];
    const current = buttons.indexOf(event.target.closest('va-button'));
    if (current === -1) return;

    let next;
    switch (event.key) {
      case 'ArrowRight': next = (current + 1) % buttons.length; break;
      case 'ArrowLeft': next = (current - 1 + buttons.length) % buttons.length; break;
      case 'Home': next = 0; break;
      case 'End': next = buttons.length - 1; break;
      default: return;
    }
    event.preventDefault();
    buttons[next].focus();
  });
}
